  static List<CatalogsFeedValidationWarnings> listFromJson(dynamic json, {bool growable = false,}) {
    final result = <CatalogsFeedValidationWarnings>[];
    if (json is List && json.isNotEmpty) {
      for (final row in json) {
        final value = CatalogsFeedValidationWarnings.fromJson(row);
        if (value != null) {
          result.add(value);
        }
      }
    }
    return result.toList(growable: growable);
  }

  static Map<String, CatalogsFeedValidationWarnings> mapFromJson(dynamic json) {
    final map = <String, CatalogsFeedValidationWarnings>{};
    if (json is Map && json.isNotEmpty) {
      json = json.cast<String, dynamic>(); // ignore: parameter_assignments
      for (final entry in json.entries) {
        final value = CatalogsFeedValidationWarnings.fromJson(entry.value);
        if (value != null) {
          map[entry.key] = value;
        }
      }
    }
    return map;
  }

  // maps a json object with a list of CatalogsFeedValidationWarnings-objects as value to a dart map
  static Map<String, List<CatalogsFeedValidationWarnings>> mapListFromJson(dynamic json, {bool growable = false,}) {
    final map = <String, List<CatalogsFeedValidationWarnings>>{};
    if (json is Map && json.isNotEmpty) {
      // ignore: parameter_assignments
      json = json.cast<String, dynamic>();
      for (final entry in json.entries) {
        map[entry.key] = CatalogsFeedValidationWarnings.listFromJson(entry.value, growable: growable,);
      }
    }
    return map;
  }

